& {
  if (-not $env:TEMP) { throw 'TEMP is not set; nothing deleted' }
  $roots = @($env:TEMP)
  $cutoff = (Get-Date).AddDays(-2)
  $deleted = 0; $failed = 0; $kept = 0; $notRead = 0; $firstError = $null
  foreach ($root in $roots) {
    if (-not (Test-Path -LiteralPath $root -PathType Container)) { "Not there, nothing to delete: $root"; continue }
    try { $rootAttributes = (Get-Item -LiteralPath $root -Force -ErrorAction Stop).Attributes } catch { $notRead++; if (-not $firstError) { $firstError = "$($root) - $($_.Exception.Message)" }; "Skipped, the folder could not be read, nothing deleted in it: $root"; continue }
    if ($rootAttributes -band [IO.FileAttributes]::ReparsePoint) { "Skipped, the folder is a link (reparse point), nothing deleted in it: $root"; continue }
    $dirs = New-Object 'System.Collections.Generic.Stack[string]'
    $dirs.Push($root)
    while ($dirs.Count -gt 0) {
      $dir = $dirs.Pop()
      Get-ChildItem -LiteralPath $dir -Directory -Force -ErrorAction SilentlyContinue -ErrorVariable dirErrors | Where-Object { -not ($_.Attributes -band [IO.FileAttributes]::ReparsePoint) } | ForEach-Object { $dirs.Push($_.FullName) }
      Get-ChildItem -LiteralPath $dir -File -Force -ErrorAction SilentlyContinue -ErrorVariable fileErrors | Where-Object { -not ([int]$_.Attributes -band 0x401000) } | ForEach-Object { if ($_.LastWriteTime -lt $cutoff -and $_.CreationTime -lt $cutoff) { try { Remove-Item -LiteralPath $_.FullName -Force -ErrorAction Stop; $deleted++ } catch { $failed++ } } else { $kept++ } }
      if ($dirErrors.Count -gt 0 -or $fileErrors.Count -gt 0) { $notRead++; if (-not $firstError) { $firstError = "$($dir) - $(@(@($dirErrors) + @($fileErrors))[0].Exception.Message)" } }
    }
  }
  "Deleted files: $deleted. Not deleted (in use or denied): $failed. Kept (written or created in the last 2 days): $kept. Folders that could not be read: $notRead."
  if ($notRead -gt 0) { "The counts are incomplete: $notRead folders could not be read, so the files in them were neither deleted nor counted. First error: $firstError" }
}

