& {
  $principal = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
  if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) { 'Not elevated: run this block in PowerShell opened with Run as administrator; nothing deleted'; return }
  if (-not $env:SystemRoot) { throw 'SystemRoot is not set; nothing deleted' }
  $roots = @((Join-Path $env:SystemRoot 'SoftwareDistribution\Download'))
  $running = @(Get-Service -Name wuauserv, bits -ErrorAction Stop | Where-Object { $_.Status -eq 'Running' } | ForEach-Object { $_.Name })
  try {
    foreach ($name in $running) { Stop-Service -Name $name -ErrorAction Stop }
    $cutoff = (Get-Date).AddDays(-10)
    $deleted = 0; $failed = 0; $kept = 0; $notRead = 0; $firstError = $null
    foreach ($root in $roots) {
      if (-not (Test-Path -LiteralPath $root -PathType Container)) { "Not there, nothing to delete: $root"; continue }
