      if ($rootAttributes -band [IO.FileAttributes]::ReparsePoint) { "Skipped, the folder is a link (reparse point), nothing deleted in it: $root"; continue }
      $dirs = New-Object 'System.Collections.Generic.Stack[string]'
      $dirs.Push($root)
      while ($dirs.Count -gt 0) {
        $dir = $dirs.Pop()
        Get-ChildItem -LiteralPath $dir -Directory -Force -ErrorAction SilentlyContinue -ErrorVariable dirErrors | Where-Object { -not ($_.Attributes -band [IO.FileAttributes]::ReparsePoint) } | ForEach-Object { $dirs.Push($_.FullName) }
        Get-ChildItem -LiteralPath $dir -File -Force -ErrorAction SilentlyContinue -ErrorVariable fileErrors | Where-Object { -not ([int]$_.Attributes -band 0x401000) } | ForEach-Object { if ($_.LastWriteTime -lt $cutoff -and $_.CreationTime -lt $cutoff) { try { Remove-Item -LiteralPath $_.FullName -Force -ErrorAction Stop; $deleted++ } catch { $failed++ } } else { $kept++ } }
        if ($dirErrors.Count -gt 0 -or $fileErrors.Count -gt 0) { $notRead++; if (-not $firstError) { $firstError = "$($dir) - $(@(@($dirErrors) + @($fileErrors))[0].Exception.Message)" } }
      }
    }
    "Deleted files: $deleted. Not deleted (in use or denied): $failed. Kept (written or created in the last 10 days): $kept. Folders that could not be read: $notRead."
    if ($notRead -gt 0) { "The counts are incomplete: $notRead folders could not be read, so the files in them were neither deleted nor counted. First error: $firstError" }
  } finally {
    foreach ($name in $running) { Start-Service -Name $name -ErrorAction Continue }
    Get-Service -Name wuauserv, bits | ForEach-Object { "$($_.Name): $($_.Status)" }
  }
}

& {
  $principal = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
  if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) { 'Not elevated: run this block in PowerShell opened with Run as administrator; nothing deleted'; return }
  if (-not $env:SystemRoot) { throw 'SystemRoot is not set; nothing deleted' }
  try {
    Delete-DeliveryOptimizationCache -Force -ErrorAction Stop
    'Delete-DeliveryOptimizationCache finished without an error'
  } catch {
    "Delete-DeliveryOptimizationCache failed: $($_.Exception.Message)"
  }
  $cache = Join-Path $env:SystemRoot 'ServiceProfiles\NetworkService\AppData\Local\Microsoft\Windows\DeliveryOptimization\Cache'
  try { $null = Get-Item -LiteralPath $cache -Force -ErrorAction Stop } catch [System.Management.Automation.ItemNotFoundException] { "The cache folder is not there, no file left: $cache"; return } catch { "Could not read the cache folder, files left not known: $($_.Exception.Message)"; return }
  $readErrors = @()
  $left = @(Get-ChildItem -LiteralPath $cache -File -Recurse -Force -ErrorAction SilentlyContinue -ErrorVariable readErrors)
  if ($readErrors.Count -gt 0) { "Could not read the cache folder in full ($($readErrors.Count) read errors), so the number of files left is not known: $($readErrors[0].Exception.Message)" }
  else { "Files left in the cache: $($left.Count)" }
}

