& {
  Get-CimInstance Win32_LogicalDisk -Filter 'DriveType=3' | ForEach-Object {
    $drive = $_.DeviceID
    try {
      Clear-RecycleBin -DriveLetter $drive.TrimEnd(':') -Force -ErrorAction Stop
      "Recycle bin emptied on drive $($drive)"
    } catch {
      $err = $_.Exception
      if (($err -is [ComponentModel.Win32Exception] -and $err.NativeErrorCode -eq 3) -or $err.Message -like '*cannot find the path specified*') { "Recycle bin already empty on drive $($drive)" }
      else { "Recycle bin NOT emptied on drive $($drive): $($err.Message)" }
    }
  }
  try { "Items left in the recycle bin of this account (all drives): $((New-Object -ComObject Shell.Application).Namespace(10).Items().Count)" }
  catch { "Could not read the recycle bin back ($($_.Exception.Message)); the next run of the skill measures it" }
}
